21	
22	/// Result of evaluating a step through the decision engine.
23	#[derive(Debug, Clone)]
24	pub struct EvaluationResult {
25	    /// The decision for this step.
26	    pub decision: StepDecision,
27	    /// Why the decision was made (human-readable).
28	    pub reason: String,
29	    /// Computed satisfaction details (if satisfaction was evaluated).
30	    pub satisfaction: Option<ComputedSatisfaction>,
31	}
32	
33	/// Context needed by the decision engine to evaluate steps.
34	pub struct EngineContext<'a> {
35	    /// All resolved steps in the workflow.
36	    pub steps: &'a HashMap<String, ResolvedStep>,
37	    /// Project root directory.
38	    pub project_root: &'a Path,
39	    /// Interpolation context for check evaluation.
40	    pub interpolation: &'a InterpolationContext,
41	    /// Snapshot store for change checks.
42	    pub snapshot_store: &'a mut SnapshotStore,
43	    /// State store for execution history.
44	    pub state: Option<&'a StateStore>,
45	    /// Per-step workflow overrides.
46	    pub step_overrides: &'a HashMap<String, StepOverride>,
47	    /// Steps forced to re-run via --force flag.
48	    pub force: &'a HashSet<String>,
49	    /// Whether every step in this workflow should be forced (--force-all).
50	    pub force_all: bool,
51	    /// Pre-evaluated named check results for cross-step refs.
52	    pub named_check_results: &'a HashMap<String, CheckResult>,
53	    /// Satisfaction cache (two-layer).
54	    pub satisfaction_cache: &'a mut SatisfactionCache,
55	    /// Steps that have already been evaluated this session (decision cache).
56	    /// Maps step name -> evaluation result.
57	    pub evaluated: HashMap<String, EvaluationResult>,
58	    /// Steps that failed execution (set by the orchestrator after execution).
59	    pub failed_steps: &'a HashSet<String>,
60	    /// Steps the user explicitly skipped.
61	    pub user_skipped_steps: &'a HashSet<String>,
62	    /// Steps confirmed as satisfied.
63	    pub satisfied_steps: &'a HashSet<String>,
64	    /// Steps with unresolved requirement gaps (after install attempts).
65	    /// The orchestrator populates this after attempting installation.
66	    pub unresolved_gaps: &'a HashSet<String>,
67	}
68	
69	/// Evaluate a step through the full decision matrix.
70	///
71	/// This is the single entry point for step decisions. It evaluates the step
72	/// through the hierarchy defined in the plan:
73	///
74	/// 1. Check decision cache (return early if already evaluated this session)
75	/// 2. Hard blocks (dependency failed/blocked, precondition failed)
76	/// 3. Force override → Run
77	/// 4. Compute satisfaction (satisfied_when > checks > rerun window)
78	/// 5. Satisfied → AutoSkip
79	/// 6. Not satisfied → sensitive? Prompt : confirm? Prompt : AutoRun
80	pub fn evaluate_step(step_name: &str, ctx: &mut EngineContext<'_>) -> EvaluationResult {
81	    // 1. Check decision cache
82	    if let Some(cached) = ctx.evaluated.get(step_name) {
83	        return cached.clone();
84	    }
85	
86	    let step = match ctx.steps.get(step_name) {
87	        Some(s) => s,
88	        None => {
89	            return EvaluationResult {
90	                decision: StepDecision::Block {
91	                    reason: BlockReason::DependencyFailed {
92	                        dependency: step_name.to_string(),
93	                    },
94	                },
95	                reason: format!("Step '{}' not found", step_name),
96	                satisfaction: None,
97	            };
98	        }
99	    };
100	
101	    // 2. Hard blocks — dependency failed
102	    if let Some(failed_dep) = step
103	        .depends_on
104	        .iter()
105	        .find(|dep| ctx.failed_steps.contains(*dep))
106	    {
107	        let result = EvaluationResult {
108	            decision: StepDecision::Block {
109	                reason: BlockReason::DependencyFailed {
110	                    dependency: failed_dep.clone(),
111	                },
112	            },
113	            reason: format!("dependency '{}' failed", failed_dep),
114	            satisfaction: None,
115	        };
116	        ctx.evaluated.insert(step_name.to_string(), result.clone());
117	        return result;
118	    }
119	
120	    // Hard block — dependency skipped and not satisfied
121	    if let Some(skipped_dep) = step
122	        .depends_on
123	        .iter()
124	        .find(|dep| ctx.user_skipped_steps.contains(*dep) && !ctx.satisfied_steps.contains(*dep))
125	    {
126	        let result = EvaluationResult {
127	            decision: StepDecision::Block {
128	                reason: BlockReason::DependencySkipped {
129	                    dependency: skipped_dep.clone(),
130	                },
131	            },
132	            reason: format!("dependency '{}' skipped and not satisfied", skipped_dep),
133	            satisfaction: None,
134	        };
135	        ctx.evaluated.insert(step_name.to_string(), result.clone());
136	        return result;
137	    }
138	
139	    // Hard block — precondition fails
140	    if let Some(precondition) = step.execution.effective_precondition() {
141	        let mut evaluator =
142	            CheckEvaluator::new(ctx.project_root, ctx.interpolation, ctx.snapshot_store);
143	        let precond_result = evaluator.evaluate(&precondition);
144	        if !precond_result.passed_check() {
145	            let result = EvaluationResult {
146	                decision: StepDecision::Block {
147	                    reason: BlockReason::PreconditionFailed {
148	                        description: precond_result.description.clone(),
149	                    },
150	                },

