6	
7	/// A cached template entry.
8	#[derive(Debug, Clone, Serialize, Deserialize)]
9	pub struct CacheEntry {
10	    /// Source ID (e.g., "http:https://example.com").
11	    pub source_id: String,
12	    /// Template name within the source.
13	    pub template_name: String,
14	    /// Path to the cached content.
15	    pub content_path: PathBuf,
16	    /// Cache metadata for validation.
17	    pub metadata: CacheMetadata,
18	}
19	
20	/// Metadata for cache validation.
21	#[derive(Debug, Clone, Serialize, Deserialize)]
22	pub struct CacheMetadata {
23	    /// When this entry was cached.
24	    pub cached_at: DateTime<Utc>,
25	    /// When the cached entry expires.
26	    pub expires_at: DateTime<Utc>,
27	    /// ETag from HTTP response, if available.
28	    pub etag: Option<String>,
29	    /// Git commit SHA, if from a git source.
30	    pub commit_sha: Option<String>,
31	    /// Size in bytes.
32	    pub size_bytes: u64,
33	}
34	
35	impl CacheEntry {
36	    /// Create a new cache entry.
37	    pub fn new(
38	        source_id: impl Into<String>,
39	        template_name: impl Into<String>,
40	        content_path: impl Into<PathBuf>,
41	        ttl_seconds: u64,
42	    ) -> Self {
43	        let now = Utc::now();
44	        let expires_at = now + chrono::Duration::seconds(ttl_seconds as i64);
45	
46	        Self {
47	            source_id: source_id.into(),
48	            template_name: template_name.into(),
49	            content_path: content_path.into(),
50	            metadata: CacheMetadata {
51	                cached_at: now,
52	                expires_at,
53	                etag: None,
54	                commit_sha: None,
55	                size_bytes: 0,
56	            },
57	        }
58	    }
59	
60	    /// Check if the entry has expired based on TTL.
61	    pub fn is_expired(&self) -> bool {
62	        Utc::now() > self.metadata.expires_at
63	    }
64	
65	    /// Get the age of this entry.
66	    pub fn age(&self) -> chrono::Duration {
67	        Utc::now().signed_duration_since(self.metadata.cached_at)
68	    }
69	
70	    /// Set ETag for HTTP validation.
71	    pub fn with_etag(mut self, etag: impl Into<String>) -> Self {
72	        self.metadata.etag = Some(etag.into());
73	        self
74	    }
75	
76	    /// Set commit SHA for git validation.
77	    pub fn with_commit_sha(mut self, sha: impl Into<String>) -> Self {
78	        self.metadata.commit_sha = Some(sha.into());
79	        self
80	    }
81	
82	    /// Set size in bytes.
83	    pub fn with_size(mut self, size: u64) -> Self {
84	        self.metadata.size_bytes = size;
85	        self
86	    }
87	
88	    /// Create a unique cache key.
89	    pub fn cache_key(&self) -> String {
90	        format!("{}:{}", self.source_id, self.template_name)
91	    }
92	}
93	
94	impl CacheMetadata {
95	    /// Calculate remaining TTL in seconds.
96	    pub fn remaining_ttl(&self) -> i64 {
97	        self.expires_at
98	            .signed_duration_since(Utc::now())
99	            .num_seconds()
100	            .max(0)
101	    }
102	}
