78	    /// alphabetical ordering for steps not in the preferred list.
79	    pub fn topological_order_stable(&self, preferred_order: &[String]) -> Result<Vec<String>> {
80	        self.topological_order_with_hint(Some(preferred_order))
81	    }
82	
83	    fn topological_order_with_hint(
84	        &self,
85	        preferred_order: Option<&[String]>,
86	    ) -> Result<Vec<String>> {
87	        // Build a position map for tie-breaking. Steps in preferred_order
88	        // sort by their position; unknown steps sort after all known ones,
89	        // then alphabetically among themselves.
90	        let position: HashMap<&str, usize> = preferred_order
91	            .map(|order| {
92	                order
93	                    .iter()
94	                    .enumerate()
95	                    .map(|(i, s)| (s.as_str(), i))
96	                    .collect()
97	            })
98	            .unwrap_or_default();
99	
100	        let sort_key = |name: &String| -> (usize, String) {
101	            match position.get(name.as_str()) {
102	                Some(&pos) => (pos, String::new()),
103	                None => (usize::MAX, name.clone()),
104	            }
105	        };
106	
107	        // Count incoming edges for each node
108	        let mut in_degree: HashMap<String, usize> = HashMap::new();
109	        for step in &self.steps {
110	            in_degree.insert(
111	                step.clone(),
112	                self.dependencies.get(step).map_or(0, |d| d.len()),
113	            );
114	        }
115	
116	        // Start with nodes that have no dependencies, sorted for determinism.
117	        let mut ready: Vec<String> = in_degree
118	            .iter()
119	            .filter(|(_, &degree)| degree == 0)
120	            .map(|(step, _)| step.clone())
121	            .collect();
122	        ready.sort_by_key(|s| sort_key(s));
123	        let mut queue: VecDeque<String> = ready.into_iter().collect();
124	
125	        let mut result = Vec::with_capacity(self.steps.len());
126	
127	        while let Some(step) = queue.pop_front() {
128	            result.push(step.clone());
129	
130	            // Reduce in-degree for all dependents, collecting newly-ready
131	            // ones in preferred/alphabetical order for determinism.
132	            if let Some(dependents) = self.dependents.get(&step) {
133	                let mut newly_ready = Vec::new();
134	                for dependent in dependents {
135	                    if let Some(degree) = in_degree.get_mut(dependent) {
136	                        *degree -= 1;
137	                        if *degree == 0 {
138	                            newly_ready.push(dependent.clone());
139	                        }
140	                    }
141	                }
142	                newly_ready.sort_by_key(|s| sort_key(s));
143	                for dep in newly_ready {
144	                    queue.push_back(dep);
145	                }
146	            }
147	        }
148	
149	        // If we haven't processed all nodes, there's a cycle
150	        if result.len() != self.steps.len() {
151	            let remaining: Vec<_> = in_degree
152	                .iter()
153	                .filter(|(_, &d)| d > 0)
154	                .map(|(s, _)| s.clone())
155	                .collect();
156	
157	            return Err(BivvyError::CircularDependency {
158	                cycle: remaining.join(" -> "),
159	            });
160	        }
161	
162	        Ok(result)
163	    }
164	
165	    /// Find a cycle in the graph, returning the path if one exists.
166	    pub fn find_cycle(&self) -> Option<Vec<String>> {
167	        #[derive(Clone, Copy, PartialEq)]
168	        enum State {
169	            Unvisited,
170	            Visiting,
171	            Visited,
172	        }
173	
174	        let mut state: HashMap<&str, State> = self
175	            .steps
176	            .iter()
177	            .map(|s| (s.as_str(), State::Unvisited))
178	            .collect();
179	
180	        let mut path: Vec<String> = Vec::new();
181	
182	        fn dfs<'a>(
183	            node: &'a str,
184	            graph: &'a DependencyGraph,
185	            state: &mut HashMap<&'a str, State>,
186	            path: &mut Vec<String>,
187	        ) -> Option<Vec<String>> {
188	            state.insert(node, State::Visiting);
189	            path.push(node.to_string());
190	
191	            if let Some(deps) = graph.dependencies.get(node) {
192	                for dep in deps {
193	                    match state.get(dep.as_str()) {
194	                        Some(State::Visiting) => {
195	                            // Found cycle - build the cycle path
196	                            let cycle_start = path.iter().position(|s| s == dep).unwrap();
197	                            let mut cycle: Vec<String> = path[cycle_start..].to_vec();
198	                            cycle.push(dep.clone());
199	                            return Some(cycle);
200	                        }
201	                        Some(State::Unvisited) | None => {
202	                            if let Some(cycle) = dfs(dep, graph, state, path) {
203	                                return Some(cycle);
204	                            }
205	                        }
206	                        Some(State::Visited) => {}
207	                    }
208	                }
209	            }
210	
211	            path.pop();
212	            state.insert(node, State::Visited);
213	            None
214	        }
215	
216	        for step in &self.steps {
217	            if state.get(step.as_str()) == Some(&State::Unvisited) {
218	                if let Some(cycle) = dfs(step, self, &mut state, &mut path) {
219	                    return Some(cycle);
220	                }
221	            }
222	        }
223	
224	        None
225	    }
