227	    /// Returns groups of steps that can execute in parallel.
228	    ///
229	    /// Each group contains steps whose dependencies are satisfied
230	    /// by all previous groups.
231	    pub fn parallel_groups(&self) -> Result<Vec<Vec<String>>> {
232	        // First ensure no cycles
233	        if let Some(cycle) = self.find_cycle() {
234	            return Err(BivvyError::CircularDependency {
235	                cycle: cycle.join(" -> "),
236	            });
237	        }
238	
239	        let mut groups: Vec<Vec<String>> = Vec::new();
240	        let mut completed: HashSet<String> = HashSet::new();
241	
242	        while completed.len() < self.steps.len() {
243	            let mut ready: Vec<String> = self
244	                .steps
245	                .iter()
246	                .filter(|s| !completed.contains(*s))
247	                .filter(|s| self.is_ready(s, &completed))
248	                .cloned()
249	                .collect();
250	
251	            if ready.is_empty() {
252	                break;
253	            }
254	
255	            // Sort for deterministic ordering
256	            ready.sort();
257	
258	            completed.extend(ready.iter().cloned());
259	            groups.push(ready);
260	        }
261	
262	        Ok(groups)
263	    }
