266	    pub fn is_ready(&self, step: &str, completed: &HashSet<String>) -> bool {
267	        match self.dependencies.get(step) {
268	            None => true,
269	            Some(deps) => deps.iter().all(|d| completed.contains(d)),
270	        }
271	    }
