122	
123	        // Initialize the persistent progress bar (pinned at terminal bottom).
124	        workflow_display.start_progress(total);
125	
126	        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
127	            let step =
128	                &self
129	                    .steps
130	                    .get(step_name)
131	                    .ok_or_else(|| BivvyError::ConfigValidationError {
132	                        message: format!("Step '{}' not found in resolved steps", step_name),
133	                    })?;
134	
135	            // Update progress bar immediately — before execution, so the user
136	            // sees "Step N/M" the moment iteration reaches this step.
137	            workflow_display.update_progress(index + 1, total, start.elapsed());
138	
139	            // Hand off to the step display for this iteration.
140	            let mut step_display = workflow_display.begin_step(index, total);
141	
142	            // Create StepManager and delegate step-level execution
143	            let step_mgr = StepManager::new(step, step_name, index, total, &theme);
144	
145	            let exec_opts = StepExecutionOptions {
146	                dry_run: options.dry_run,
147	                interactive,
148	                diagnostic_funnel: options.diagnostic_funnel,
149	                project_root,
150	                base_env,
151	                process_env,
152	                force_steps: &options.force,
153	                force_all: options.force_all,
154	                provided_requirements: &options.provided_requirements,
155	            };
156	
157	            let action = step_mgr.execute(
158	                &exec_opts,
159	                &mut context,
160	                step_overrides,
161	                &mut gap_checker,
162	                &mut self.snapshot_store,
163	                &self.steps,
164	                state.as_deref(),
165	                satisfaction_cache,
166	                &failed_steps,
167	                &user_skipped_steps,
168	                &satisfied_steps,
169	                &mut named_check_results,
170	                &results,
171	                ui,
172	                step_display.as_mut(),
173	                event_bus,
174	            )?;
175	
176	            // Update workflow state based on step action.
177	            // The workflow only tracks aggregate state (satisfied/failed/skipped sets)
178	            // — all per-step decisions are made by StepManager via the decision engine.
179	            match action {
180	                StepAction::Completed(result) => {
181	                    satisfied_steps.insert(step_name.clone());
182	
183	                    // Record successful execution in satisfaction cache
184	                    let record = SatisfactionRecord {
185	                        satisfied: true,
186	                        source: crate::state::satisfaction::SatisfactionSource::ExecutionHistory,
187	                        recorded_at: chrono::Utc::now(),
188	                        evidence: crate::state::satisfaction::SatisfactionEvidence::HistoricalRun {
189	                            ran_at: chrono::Utc::now(),
190	                            exit_code: result.exit_code.unwrap_or(0),
191	                        },
192	                        config_hash: None,
193	                        step_hash: None,
194	                    };
195	                    satisfaction_cache.store(step_name, record);
196	
197	                    results.push(result);
198	                }
199	
200	                StepAction::Skipped(result, category) => {
201	                    // StepManager classifies the skip reason so the workflow
202	                    // doesn't need to inspect StepResult internals.
203	                    match category {
204	                        SkipCategory::Satisfied => {
205	                            satisfied_steps.insert(step_name.clone());
206	                        }
207	                        SkipCategory::UserDeclined | SkipCategory::DependencySkipped => {
208	                            user_skipped_steps.insert(step_name.clone());
209	                        }
210	                        SkipCategory::RecoverySkipped | SkipCategory::Other => {
211	                            // Recovery-skipped steps do NOT block dependents —
212	                            // the user chose to move past the failure.
213	                        }
214	                    }
215	                    results.push(result);
216	                }
217	
218	                StepAction::Failed(result) => {
219	                    all_success = false;
220	                    if !step.behavior.allow_failure {
221	                        failed_steps.insert(step_name.clone());
222	                    }
223	                    results.push(result);
224	                }
225	
226	                StepAction::Blocked => {
227	                    all_success = false;
228	                    failed_steps.insert(step_name.clone());
229	                }
230	
231	                StepAction::Aborted(result) => {
232	                    results.push(result);
233	                    workflow_aborted = true;
234	                    all_success = false;
235	                    break;
236	                }
237	            }
238	
239	            // Update progress bar after step completes (reflects final position)
240	            workflow_display.update_progress(index + 1, total, start.elapsed());
241	        }
242	
243	        // Flush satisfaction cache to disk
244	        if !options.dry_run {
245	            if let Err(e) = satisfaction_cache.flush() {
246	                tracing::warn!("Failed to flush satisfaction cache: {}", e);
247	            }
248	        }
249	
250	        // Finish progress bar (clear before summary)
251	        workflow_display.finish_progress();
252	
253	        let mut all_skipped: Vec<String> = plan.flag_skipped.into_iter().collect();
254	        all_skipped.extend(plan.env_skipped);
255	
256	        let steps_run = results.len();
257	        let steps_skipped_count = all_skipped.len();
258	        let duration = start.elapsed();
259	
260	        event_bus.emit(&BivvyEvent::WorkflowCompleted {
261	            name: workflow_name.to_string(),
262	            success: all_success,
263	            aborted: workflow_aborted,
264	            steps_run,
265	            steps_skipped: steps_skipped_count,
266	            duration_ms: duration.as_millis() as u64,
267	        });
268	
269	        Ok(WorkflowResult {
270	            workflow: workflow_name.to_string(),
271	            steps: results,
272	            skipped: all_skipped,
273	            duration,
274	            success: all_success,
275	            aborted: workflow_aborted,
276	        })
277	    }
278	}
