15	/// Initialize the tracing subscriber for logging.
16	///
17	/// Log level is controlled by:
18	/// 1. `--debug` flag sets level to DEBUG
19	/// 2. `RUST_LOG` environment variable (if set)
20	/// 3. Default is INFO
21	fn init_tracing(debug: bool) {
22	    let filter = if debug {
23	        EnvFilter::new("bivvy=debug")
24	    } else {
25	        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
26	    };
27	
28	    tracing_subscriber::registry()
29	        .with(fmt::layer().with_target(false))
30	        .with(filter)
31	        .init();
32	}
33	
34	fn main() -> ExitCode {
35	    // Safety net: claim the foreground process group for terminal I/O.
36	    //
37	    // When `cargo run` (or other launchers) spawn bivvy, the child may
38	    // not be the terminal's foreground process group. We ignore SIGTTOU
39	    // (so tcsetpgrp doesn't suspend us) and claim the foreground.
40	    //
41	    // The primary defense against SIGTTOU is using `-lc` (not `-lic`)
42	    // for child shell commands — see shell/command.rs. Without `-i`,
43	    // child shells don't set up job control and don't steal the
44	    // foreground group. These signal ignores and tcsetpgrp call are a
45	    // safety net for edge cases (e.g., `cargo run` wrappers).
46	    #[cfg(unix)]
47	    unsafe {
48	        libc::signal(libc::SIGTTOU, libc::SIG_IGN);
49	        libc::signal(libc::SIGTTIN, libc::SIG_IGN);
50	
51	        let tty_fd = libc::open(c"/dev/tty".as_ptr(), libc::O_RDWR);
52	        if tty_fd >= 0 {
53	            libc::tcsetpgrp(tty_fd, libc::getpgrp());
54	            libc::close(tty_fd);
55	        }
56	    }
57	
58	    // Background self-update process: when invoked with this env var,
59	    // perform the update check/download and exit immediately.
60	    if std::env::var("BIVVY_SELF_UPDATE_BG").is_ok() {
61	        let _ = perform_background_update();
62	        return ExitCode::SUCCESS;
63	    }
64	
65	    let cli = Cli::parse();
66	    init_tracing(cli.debug);
67	
68	    // Ensure ~/.bivvy/config.yml exists (first-run bootstrap).
69	    bivvy::config::ensure_global_config();
70	
71	    tracing::debug!("Bivvy starting with args: {:?}", cli);
72	
73	    // Determine output mode
74	    let output_mode = if cli.quiet {
75	        OutputMode::Quiet
76	    } else if cli.verbose {
77	        OutputMode::Verbose
78	    } else {
79	        OutputMode::Normal
80	    };
81	
82	    // Handle --no-color
83	    if cli.no_color {
84	        std::env::set_var("NO_COLOR", "1");
85	    }
86	
87	    // Determine project root
88	    let project_root = cli
89	        .project
90	        .as_ref()
91	        .cloned()
92	        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
93	
94	    // Check if non-interactive (CI mode or explicit flag)
95	    let is_interactive = match &cli.command {
96	        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
97	        _ => !is_ci(),
98	    };
