1	//! Satisfaction cache types and persistence.
2	//!
3	//! The satisfaction cache is the core data structure of bivvy's decision engine.
4	//! It records what bivvy knows about each step's satisfaction state — whether the
5	//! step's purpose is already fulfilled — and persists that knowledge across sessions.
6	//!
7	//! # Two-Layer Architecture
8	//!
9	//! The cache operates at two layers:
10	//! - **Persisted layer** (`satisfaction.json`): survives across sessions
11	//! - **Runtime layer** (in-memory `HashMap`): working copy for one session
12	//!
13	//! The runtime layer is seeded from the persisted layer on startup, updated as
14	//! steps are evaluated, and flushed back to disk at the end.
15	
16	use std::collections::HashMap;
17	use std::path::{Path, PathBuf};
18	
19	use chrono::{DateTime, Utc};
20	use serde::{Deserialize, Serialize};
21	
22	/// A persisted record of a step's satisfaction state.
23	///
24	/// Contains the satisfaction decision, the signal that produced it, and the
25	/// verifiable evidence that supports it. Used for both runtime decisions and
26	/// cross-session persistence.
27	#[derive(Debug, Clone, Serialize, Deserialize)]
28	pub struct SatisfactionRecord {
29	    /// Whether the step is satisfied.
30	    pub satisfied: bool,
31	
32	    /// What signal produced the satisfaction (or lack thereof).
33	    pub source: SatisfactionSource,
34	
35	    /// When this record was created or last updated.
36	    pub recorded_at: DateTime<Utc>,
37	
38	    /// The specific evidence that supports this record.
39	    /// Used for fast cross-session validation.
40	    pub evidence: SatisfactionEvidence,
41	
42	    /// Hash of the step's check configuration at the time of recording.
43	    /// If the config changes, this record is invalidated.
44	    #[serde(default, skip_serializing_if = "Option::is_none")]
45	    pub config_hash: Option<String>,
46	
47	    /// Hash of the step's definition (command, deps, tools) at recording time.
48	    /// If the definition changes, this record is invalidated.
49	    #[serde(default, skip_serializing_if = "Option::is_none")]
50	    pub step_hash: Option<String>,
51	}
52	
53	/// What signal produced a satisfaction decision.
54	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
55	pub enum SatisfactionSource {
56	    /// A file or binary exists at the expected path.
57	    PresenceCheck,
58	    /// Target hash matches baseline — nothing changed since last run.
59	    ChangeCheck,
60	    /// A check command succeeded.
61	    ExecutionCheck,
62	    /// Explicit `satisfied_when` conditions passed.
63	    ExplicitCondition,
64	    /// Step ran successfully within the rerun window.
65	    ExecutionHistory,
66	    /// No data yet — step has never been evaluated.
67	    NeverEvaluated,
68	}
69	
70	/// The verifiable evidence behind a satisfaction decision.
71	///
72	/// Each variant carries enough data to re-validate cheaply across sessions.
73	/// Presence checks need a stat(), change checks need a hash compare,
74	/// execution history needs a timestamp check.
75	#[derive(Debug, Clone, Serialize, Deserialize)]
76	pub enum SatisfactionEvidence {
77	    /// File or binary exists at this path.
78	    /// Validate: `stat()` the path.
79	    Presence { target: String, kind: PresenceKind },
80	
81	    /// Target hash matches baseline.
82	    /// Validate: rehash the target, compare.
83	    ChangeBaseline { target: String, hash: String },
84	
85	    /// Command exited 0.
86	    /// Validate: re-run the command (expensive — only for execution checks).
87	    CommandSuccess { command: String },
88	
89	    /// Step ran successfully at this time.
90	    /// Validate: check if `ran_at` is within the rerun window.
91	    HistoricalRun {
92	        ran_at: DateTime<Utc>,
93	        exit_code: i32,
94	    },
95	
96	    /// Multiple pieces of evidence (for `satisfied_when` with multiple conditions).
97	    Composite(Vec<SatisfactionEvidence>),
98	
99	    /// No evidence (step has never been evaluated).
100	    None,
101	}
102	
103	/// Kind of presence evidence.
104	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
105	pub enum PresenceKind {
106	    /// A file path exists.
107	    File,
108	    /// A binary is found on PATH.
109	    Binary,
110	    /// A custom command check.
111	    Custom,
112	}
113	
114	impl SatisfactionEvidence {
115	    /// Validate this evidence against the current state of the world.
116	    ///
117	    /// Returns `true` if the evidence still holds. Validation cost varies by type:
118	    /// - `Presence` — stat() call (~microseconds)
119	    /// - `ChangeBaseline` — rehash + compare (~milliseconds)
120	    /// - `HistoricalRun` — timestamp arithmetic (instant)
121	    /// - `CommandSuccess` — requires re-running the command (expensive, returns false to force re-evaluation)
122	    /// - `Composite` — validates each sub-evidence
123	    /// - `None` — always invalid
124	    pub fn validate(&self, project_root: &Path) -> bool {
125	        match self {
126	            SatisfactionEvidence::Presence { target, kind } => match kind {
127	                PresenceKind::File => {
128	                    let path = if Path::new(target).is_absolute() {
129	                        std::path::PathBuf::from(target)
130	                    } else {
131	                        project_root.join(target)
132	                    };
133	                    path.exists()
134	                }
135	                PresenceKind::Binary => {
136	                    // Check if binary is on PATH
137	                    crate::sys::find_on_path(target).is_some()
138	                }
139	                PresenceKind::Custom => {
140	                    // Custom presence checks can't be cheaply validated
141	                    false
142	                }
143	            },
144	            SatisfactionEvidence::ChangeBaseline { .. } => {
145	                // Rehashing requires the snapshot store — defer to the caller
146	                // For now, return false to force re-evaluation
147	                false
148	            }
149	            SatisfactionEvidence::CommandSuccess { .. } => {
150	                // Re-running a command is expensive — always re-evaluate
151	                false
152	            }
153	            SatisfactionEvidence::HistoricalRun { ran_at, exit_code } => {
154	                // Valid if the run succeeded (exit 0) — the rerun window check
155	                // is done by the caller since it depends on step configuration
156	                *exit_code == 0 && *ran_at <= Utc::now()
157	            }
158	            SatisfactionEvidence::Composite(evidence_list) => {
159	                evidence_list.iter().all(|e| e.validate(project_root))
160	            }
161	            SatisfactionEvidence::None => false,
162	        }
163	    }
164	}
165	
166	/// Two-layer satisfaction cache: persisted JSON on disk + runtime HashMap in memory.
167	///
168	/// During a `bivvy run`:
169	/// 1. Load persisted records from `satisfaction.json`
170	/// 2. As steps are evaluated, store results in the runtime layer
171	/// 3. At the end (or after each step for crash recovery), flush to disk
172	///
173	/// The runtime layer takes precedence over the persisted layer.
174	pub struct SatisfactionCache {
175	    /// Runtime layer — the working copy for this session.
176	    runtime: HashMap<String, SatisfactionRecord>,
177	    /// Persisted layer — loaded from disk at session start.
178	    persisted: HashMap<String, SatisfactionRecord>,
179	    /// Path to the satisfaction.json file.
180	    path: PathBuf,
181	}
182	
183	impl SatisfactionCache {
184	    /// Create an empty cache (for new projects or `--fresh` mode).
185	    pub fn empty(path: PathBuf) -> Self {
186	        Self {
187	            runtime: HashMap::new(),
188	            persisted: HashMap::new(),
189	            path,
190	        }
191	    }
192	
193	    /// Load the cache from a `satisfaction.json` file.
194	    ///
195	    /// If the file doesn't exist or is invalid, returns an empty cache.
196	    pub fn load(path: PathBuf) -> Self {
197	        let persisted = if path.exists() {
198	            match std::fs::read_to_string(&path) {
199	                Ok(content) => serde_json::from_str(&content).unwrap_or_default(),
200	                Err(_) => HashMap::new(),
201	            }
202	        } else {
203	            HashMap::new()
204	        };
205	
206	        Self {
207	            runtime: HashMap::new(),
208	            persisted,
209	            path,
210	        }
211	    }
212	
213	    /// Get a satisfaction record for a step.
214	    ///
215	    /// Checks the runtime layer first, then the persisted layer.
216	    /// Persisted records are validated before being returned — if the evidence
217	    /// is stale or the config/step hash doesn't match, the record is discarded.
218	    pub fn get(
219	        &self,
220	        step: &str,
221	        project_root: &Path,
222	        config_hash: Option<&str>,
223	        step_hash: Option<&str>,
224	    ) -> Option<&SatisfactionRecord> {
225	        // Runtime layer takes precedence — no validation needed (just computed)
226	        if let Some(record) = self.runtime.get(step) {
227	            return Some(record);
228	        }
229	
230	        // Check persisted layer with validation
231	        if let Some(record) = self.persisted.get(step) {
232	            // Structural invalidation: config or step definition changed
233	            if let Some(expected) = config_hash {
234	                if record.config_hash.as_deref() != Some(expected) {
235	                    return None;
236	                }
237	            }
238	            if let Some(expected) = step_hash {
239	                if record.step_hash.as_deref() != Some(expected) {
240	                    return None;
241	                }
242	            }
243	
244	            // Evidence validation
245	            if record.evidence.validate(project_root) {
246	                return Some(record);
247	            }
248	        }
249	
250	        None
251	    }
252	
253	    /// Get a satisfaction record from the runtime layer only (no validation).
254	    pub fn get_runtime(&self, step: &str) -> Option<&SatisfactionRecord> {
255	        self.runtime.get(step)
256	    }
257	
258	    /// Store a satisfaction record in the runtime layer.
259	    pub fn store(&mut self, step: &str, record: SatisfactionRecord) {
260	        self.runtime.insert(step.to_string(), record);
261	    }
262	
263	    /// Check if a step has any record (runtime or persisted, without validation).
264	    pub fn has_record(&self, step: &str) -> bool {
265	        self.runtime.contains_key(step) || self.persisted.contains_key(step)
266	    }
267	
268	    /// Invalidate a specific step's records from both layers.
269	    pub fn invalidate(&mut self, step: &str) {
270	        self.runtime.remove(step);
271	        self.persisted.remove(step);
272	    }
273	
274	    /// Invalidate all records (for `--fresh` mode).
275	    pub fn invalidate_all(&mut self) {
276	        self.runtime.clear();
277	        self.persisted.clear();
278	    }
279	
280	    /// Flush the runtime cache to disk as `satisfaction.json`.
281	    ///
282	    /// Merges runtime records into persisted records (runtime wins on conflict),
283	    /// then writes the combined result to disk using atomic write.
284	    pub fn flush(&mut self) -> std::io::Result<()> {
285	        // Merge runtime into persisted
286	        for (step, record) in &self.runtime {
287	            self.persisted.insert(step.clone(), record.clone());
288	        }
289	
290	        // Ensure parent directory exists
291	        if let Some(parent) = self.path.parent() {
292	            std::fs::create_dir_all(parent)?;
293	        }
294	
295	        // Atomic write: temp file then rename
296	        let content =
297	            serde_json::to_string_pretty(&self.persisted).map_err(std::io::Error::other)?;
298	        let temp_path = self.path.with_extension("json.tmp");
299	        std::fs::write(&temp_path, &content)?;
300	        std::fs::rename(&temp_path, &self.path)?;
301	
302	        Ok(())
303	    }
304	
305	    /// Get the path to the satisfaction.json file.
306	    pub fn path(&self) -> &Path {
307	        &self.path
308	    }
309	
310	    /// Get the number of records in the runtime layer.
311	    pub fn runtime_len(&self) -> usize {
312	        self.runtime.len()
313	    }
314	
315	    /// Get the number of records in the persisted layer.
316	    pub fn persisted_len(&self) -> usize {
317	        self.persisted.len()
318	    }
319	}
