//! Cache storage implementation.
//!
//! All writes use atomic rename (write to temp file, then rename into place)
//! and per-entry file locking to prevent corruption from concurrent access.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs::{self, File, OpenOptions};
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

/// RAII file lock that releases on drop.
struct FileLock {
    _file: File,
}

impl FileLock {
    fn acquire(path: &Path) -> Result<Self> {
        let file = OpenOptions::new()
            .create(true)
            .truncate(false)
            .write(true)
            .open(path)
            .with_context(|| format!("Failed to open lock file {:?}", path))?;

        Self::lock_exclusive(&file)?;

        Ok(Self { _file: file })
    }

    #[cfg(unix)]
    fn lock_exclusive(file: &File) -> Result<()> {
        use std::os::unix::io::AsRawFd;
        let ret = unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) };
        if ret != 0 {
            anyhow::bail!("Failed to acquire exclusive file lock");
        }
        Ok(())
    }

    #[cfg(not(unix))]
    fn lock_exclusive(_file: &File) -> Result<()> {
        Ok(())
    }
}

#[cfg(unix)]
impl Drop for FileLock {
    fn drop(&mut self) {
        use std::os::unix::io::AsRawFd;
        unsafe {
            libc::flock(self._file.as_raw_fd(), libc::LOCK_UN);
        }
    }
}

/// Write content to a temporary file then atomically rename into place.
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let temp_path = path.with_extension("tmp");
    fs::write(&temp_path, content)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path)
        .inspect_err(|_| {
            let _ = fs::remove_file(&temp_path);
        })
        .with_context(|| format!("Failed to rename temp file to {:?}", path))
}

